<script lang="ts">
 import MonthCalendar from '$lib/calendar/MonthCalendar.svelte';
 import SlideToConfirm from '$lib/components/SlideToConfirm.svelte';
 import {enhance} from '$app/forms';
 import type {PageData,ActionData} from './$types';
 let {data,form}:{data:PageData;form:ActionData}=$props();
 let selected=$state('');
 let approvalForm=$state<HTMLFormElement>();

 const chosen=$derived(data.sources.find(s=>s.fact_id===(selected||data.sourceId)));
 const approvalDraft=$derived(data.draft?.draft??data.proposalDraft);
 function localDate(s:string){return new Intl.DateTimeFormat('de-CH',{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/Zurich'}).format(new Date(s));}
 function clock(s:string){return new Intl.DateTimeFormat('de-CH',{timeStyle:'short',timeZone:'Europe/Zurich'}).format(new Date(s));}
 function localInput(iso:string){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Zurich',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(iso)).replace(' ','T');}
 function dateLabel(date:string,end:string|null){const fmt=(value:string)=>new Intl.DateTimeFormat('de-CH',{dateStyle:'medium',timeZone:'Europe/Zurich'}).format(new Date(value+'T12:00:00Z'));return end&&end!==date?`${fmt(date)} – ${fmt(end)}`:fmt(date);}
 function previousDay(date:string){const value=new Date(date+'T12:00:00Z');value.setUTCDate(value.getUTCDate()-1);return value.toISOString().slice(0,10);}
 function suggested(which:'start'|'end'){if(chosen?.suggestion)return localInput(chosen.suggestion[which]);const v=chosen?.value_text??'',date=chosen?.valid_from?.slice(0,10)??v.match(/\d{4}-\d\d-\d\d/)?.[0]??'';const times=v.match(/\d{1,2}:\d\d/g);return date&&times?.[which==='start'?0:1]?date+'T'+times[which==='start'?0:1].padStart(5,'0'):'';}
 function approve(){if(!approvalForm)return;const marker=approvalForm.elements.namedItem('approve') as HTMLInputElement;marker.value='yes';approvalForm.requestSubmit();}
</script>
<svelte:head><title>Kalender · Folio</title><meta name="referrer" content="no-referrer"/></svelte:head>
<main>
 <a href="/settings#calendar" class="settings-link">Kalendereinstellungen</a>
 <header><div><span>FOLIO</span><h1>Kalender</h1></div>{#if data.connected}<small>{data.warning?'Abgleich gestört':data.state.writeEnabled?'Mit Freigabe schreiben':'Lesend verbunden'}</small>{/if}</header>
 {#if form?.message}<p class="notice" role="status">{form.message}</p>{/if}
 {#if data.proposalState==='existing'}<p class="notice" role="status">Dieser Termin ist bereits im Kalender. Der offene Vorschlag wurde entfernt.</p>{/if}
 {#if data.warning}<p class="warning" role="alert">{data.warning}{#if data.state.syncedAt} Letzter Abgleich: {new Date(data.state.syncedAt).toLocaleString('de-CH',{timeZone:'Europe/Zurich'})}.{/if} <a href="/settings#calendar">Verbindung prüfen →</a></p>{/if}
 {#if !data.connected || !data.state.calendarId}<section><a class="connect" href="/settings#calendar">Kalender verbinden</a></section>{/if}
 {#if data.state.calendarId}<MonthCalendar events={data.state.events}/>{/if}
 {#if approvalDraft}<section class="approval"><span>TERMIN FREIGEBEN</span><h2>{approvalDraft.summary}</h2>{#if approvalDraft.allDay}<p>{dateLabel(approvalDraft.start,previousDay(approvalDraft.end))} · ganztägig</p>{:else}<p>{localDate(approvalDraft.start)} – {clock(approvalDraft.end)}</p>{/if}{#if approvalDraft.location}<p>{approvalDraft.location}</p>{/if}{#if approvalDraft.assumption}<p class="warning">{approvalDraft.assumption}</p>{/if}{#if approvalDraft.attendees?.length}<div class="invitees"><span>EINLADUNGEN</span>{#each approvalDraft.attendees as invitee}<p><strong>{invitee.role}</strong><small>{invitee.email}</small></p>{/each}</div>{/if}<small>{data.state.calendarName} · {approvalDraft.attendees?.length?`${approvalDraft.attendees.length} Einladungen werden nach Freigabe versandt`:'ohne Einladungen'}</small>{#if !data.draft || data.draft.status==='pending'}{#if data.state.writeEnabled}<form bind:this={approvalForm} method="POST" action={data.draft?'?/create':'?/createProposal'} use:enhance>{#if data.draft}<input type="hidden" name="draftId" value={data.draft.id}/>{:else}<input type="hidden" name="sourceId" value={approvalDraft.sourceId}/>{/if}<input type="hidden" name="approve" value="no"/><SlideToConfirm label={approvalDraft.attendees?.length?`Termin anlegen und ${approvalDraft.attendees.length} Einladungen senden`:'Termin verbindlich anlegen'} hint={approvalDraft.attendees?.length?'Google versendet die angezeigten Kalendereinladungen':'Schreibt genau diesen Vorschlag in deinen Kalender'} resetKey={data.draft?.id??approvalDraft.sourceId} onconfirm={approve}/></form>{:else}<p><a href="/settings#calendar">Schreibzugriff aktivieren →</a></p>{/if}{:else}<p>{data.draft.status==='created'?'Angelegt':data.draft.status==='existing'?'Bereits vorhanden':data.draft.status}</p>{/if}</section>{/if}
 {#if data.state.calendarId && !approvalDraft}
 <section class="proposal-queue"><div class="section-heading"><div><span class="eyebrow">MAIL → KALENDER</span><h2>Terminvorschläge</h2></div><strong class="count">{data.queue.open.length}</strong></div>
  {#if !data.queue.open.length}<p class="empty">Keine offenen Terminvorschläge. {data.queue.existing.length} erkannte Termine sind bereits im Kalender.</p>{/if}
  {#each data.queue.open as item (item.id)}{#if item.status==='ready'}<a class="proposal" class:active={data.proposalId===item.sourceId} href={'/calendar?proposal='+encodeURIComponent(item.sourceId)}><div><span class="status">Eintragsbereit · {item.candidate?'Modellvorschlag':'bestätigte Quelle'}{#if item.evidenceCount>1} · {item.evidenceCount} Belege{/if}</span><h3>{item.title}</h3><p>{dateLabel(item.date,item.endDate)}{#if item.draft?.allDay} · ganztägig{/if}</p></div><span aria-hidden="true">→</span></a>{:else}<a class="proposal" class:active={chosen?.fact_id===item.sourceId} href={item.href}><div><span class="status">Angaben fehlen · {item.candidate?'Modellvorschlag':'bestätigte Quelle'}{#if item.evidenceCount>1} · {item.evidenceCount} Belege{/if}</span><h3>{item.title}</h3><p>{dateLabel(item.date,item.endDate)}</p></div><span aria-hidden="true">→</span></a>{/if}{/each}
  {#if data.queue.existing.length}<details><summary>Bereits im Kalender ({data.queue.existing.length})</summary>{#each data.queue.existing as item (item.id)}<p class="compact-row"><span>{dateLabel(item.date,item.endDate)}</span>{item.title}</p>{/each}</details>{/if}
 </section>
 {#if chosen}<section><div class="section-heading"><h2>Vorschlag prüfen</h2><a class="other" href="/calendar" onclick={()=>selected=''}>Schliessen</a></div><p class="source">{chosen.value_text}</p>{#if data.matches[chosen.fact_id]}<p class="notice">Bereits im Kalender. Es wird keine Dublette angelegt.</p>{:else if data.conflicts[chosen.fact_id]}<p class="warning">{data.conflicts[chosen.fact_id]}</p>{:else if chosen.suggestion?.allDay}<p class="notice">{dateLabel(chosen.suggestion.start,previousDay(chosen.suggestion.end))} · ganztägig. Keine Uhrzeit wird erfunden.</p><a class="connect" href={'/calendar?proposal='+encodeURIComponent(chosen.fact_id)}>Freigabevorschau öffnen</a>{:else}{#key chosen.fact_id}<form method="POST" action="?/prepare" use:enhance><input type="hidden" name="sourceId" value={chosen.fact_id}/><label>Titel<input name="summary" value={chosen.suggestion?.summary??chosen.value_text} maxlength="500" required/></label><label>Ort<input name="location" value={chosen.suggestion?.location??''} maxlength="500"/></label><div class="dates"><label>Beginn<input name="start" type="datetime-local" value={suggested('start')} required/></label><label>Ende<input name="end" type="datetime-local" value={suggested('end')} required/></label></div>{#if chosen.suggestion?.assumption}<p class="warning">{chosen.suggestion.assumption}</p>{/if}<button>Prüfen</button></form>{/key}{/if}</section>{/if}
 <section id="deadlines" class="secondary-section"><div class="section-heading"><div><span class="eyebrow">NICHT IM TERMINSTACK</span><h2>Fristen &amp; Belege</h2></div><strong class="count">{data.queue.deadlines.length}</strong></div><p class="boundary">Diese Quellen bleiben mit ihren Belegen erhalten, erscheinen aber nicht als Terminbestätigung. Die spätere Buchung erfolgt erst nach Abgleich mit eingelesenen Kontoauszügen.</p>{#if data.queue.deadlines.length}<details><summary>Ansehen</summary>{#each data.queue.deadlines as item (item.id)}<p class="compact-row"><span>{dateLabel(item.date,item.endDate)}</span>{item.title}{#if item.evidenceCount>1} · {item.evidenceCount} Belege{/if}</p>{/each}</details>{/if}</section>
 {/if}


</main>
<style>
 @font-face{font-family:CalendarDisplay;src:url('/fonts/epilogue-latin-500-normal.woff2') format('woff2');font-display:swap}@font-face{font-family:CalendarBody;src:url('/fonts/dm-sans-latin-400-normal.woff2') format('woff2');font-display:swap}
 main{max-width:1400px;margin:auto;padding:28px 24px 80px;color:var(--color-foreground);background:var(--color-background);font-family:inherit;min-height:100vh}header{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:30px 0}header span,.approval>span{font:500 11px ui-monospace,monospace;letter-spacing:.12em;color:var(--color-foreground)}h1{font:500 34px system-ui,sans-serif;margin:12px 0 0}h2{font:500 19px system-ui,sans-serif;margin:0 0 16px}h3{font:500 15px system-ui,sans-serif;margin:5px 0}p{line-height:1.5}section{border:1px solid var(--color-border);border-radius:10px;padding:22px;margin:20px 0;background:var(--color-card)}label{display:grid;gap:7px;margin:14px 0;font-size:14px}input{box-sizing:border-box;width:100%;min-width:0;padding:11px;border:1px solid var(--color-border);border-radius:6px;font:inherit;background:var(--color-background);color:inherit}button,a.connect{display:inline-block;text-decoration:none;background:var(--color-foreground);color:var(--color-background);border:0;border-radius:6px;padding:12px 16px;font:500 14px system-ui;cursor:pointer;min-height:44px;box-sizing:border-box}button:disabled{opacity:.45;cursor:not-allowed}.dates{display:flex;flex-wrap:wrap;gap:12px;margin:16px 0}.dates>*{flex:1;min-width:200px}.notice,.warning{padding:14px;background:var(--color-muted);border-left:3px solid var(--color-border);font-size:14px;line-height:1.6}.warning{border-color:var(--color-foreground)}.source{font-size:16px}small{display:block;font-size:12px;color:var(--color-muted-foreground);overflow-wrap:anywhere;line-height:1.6}.approval{border:2px solid var(--color-border)}.approval form{margin-top:18px}.invitees{margin:16px 0;padding:13px 14px;border:1px solid var(--color-border);border-radius:7px;background:var(--color-muted)}.invitees>span{font:600 10px ui-monospace,monospace;letter-spacing:.08em}.invitees p{display:flex;align-items:baseline;gap:10px;margin:8px 0 0}.invitees strong{font-size:13px}.invitees small{display:inline}a{color:var(--color-foreground)}.section-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.section-heading h2{margin:3px 0 0}.eyebrow,.status{font:500 10px ui-monospace,monospace;letter-spacing:.08em;color:var(--color-muted-foreground)}.count{font:500 26px system-ui}.proposal{display:flex;align-items:center;justify-content:space-between;gap:18px;width:100%;padding:14px 0;border:0;border-top:1px solid var(--color-border);border-radius:0;background:transparent;color:inherit;text-align:left;text-decoration:none}.proposal.active{background:var(--color-muted);margin:0 -10px;padding:14px 10px;border-radius:7px}.proposal p{margin:0;font-size:13px;color:var(--color-muted-foreground)}.proposal>span{font-size:20px}.empty,.boundary{font-size:14px;color:var(--color-muted-foreground)}details{margin-top:14px;border-top:1px solid var(--color-border);padding-top:12px}summary{cursor:pointer;font-size:13px}.compact-row{display:grid;grid-template-columns:minmax(120px,auto) 1fr;gap:10px;margin:10px 0;font-size:12px}.compact-row span{color:var(--color-muted-foreground)}.secondary-section{background:var(--color-muted)}.other{display:inline-block;font-size:13px;margin-top:12px}:focus-visible{outline:2px solid var(--color-foreground);outline-offset:3px}@media(max-width:600px){main{padding:20px 16px 60px}section{padding:16px}h1{font-size:29px}header{align-items:flex-start;flex-direction:column;gap:8px}.dates>*{min-width:100%}.connect{width:100%}.compact-row{grid-template-columns:1fr;gap:2px}.invitees p{align-items:flex-start;flex-direction:column;gap:2px}}
</style>
